import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.mrTIYZc5.js";const p=JSON.parse('{"title":"CNCF Sandbox Application — Docker Secret Operator (DSO)","description":"","frontmatter":{},"headers":[],"relativePath":"cncf/CNCF_SANDBOX_APPLICATION.md","filePath":"cncf/CNCF_SANDBOX_APPLICATION.md"}'),n={name:"cncf/CNCF_SANDBOX_APPLICATION.md"};function i(s,e,c,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="cncf-sandbox-application-—-docker-secret-operator-dso" tabindex="-1">CNCF Sandbox Application — Docker Secret Operator (DSO) <a class="header-anchor" href="#cncf-sandbox-application-—-docker-secret-operator-dso" aria-label="Permalink to &quot;CNCF Sandbox Application — Docker Secret Operator (DSO)&quot;">​</a></h1><h2 id="project-description" tabindex="-1">Project Description <a class="header-anchor" href="#project-description" aria-label="Permalink to &quot;Project Description&quot;">​</a></h2><p>Docker Secret Operator (DSO) is a reconciliation engine that syncs secrets from cloud providers (AWS Secrets Manager, Azure Key Vault, HashiCorp Vault, Huawei CSMS) into Docker containers at runtime.</p><p>It runs as a lightweight agent on the Docker host. You define which secrets your containers need in a YAML file, and DSO handles the rest — fetching, caching, injecting, and automatically rotating secrets when they change upstream.</p><p>The project ships as a native Docker CLI plugin (<code>docker dso up -d</code>) and is written in Go. It uses about 20MB of RAM and runs as a systemd service.</p><p><strong>Repository:</strong> <a href="https://github.com/docker-secret-operator/dso" target="_blank" rel="noreferrer">https://github.com/docker-secret-operator/dso</a><br><strong>License:</strong> Apache-2.0<br><strong>Language:</strong> Go<br><strong>Current version:</strong> v3.0.0</p><h2 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h2><p>Docker&#39;s ecosystem has a secret management gap.</p><p>If you use Kubernetes, you have the External Secrets Operator, Sealed Secrets, and native <code>Secret</code> resources. The reconciliation model is well-established — controllers continuously ensure desired state matches actual state.</p><p>If you use plain Docker or Docker Compose, your options are:</p><ul><li><strong><code>.env</code> files</strong> — Insecure. They sit on disk, get committed to git, and fail compliance audits</li><li><strong>Docker Swarm secrets</strong> — Requires Swarm mode, which most teams don&#39;t use in 2026</li><li><strong>Manual injection</strong> — Scripting <code>docker run -e</code> with values pulled from a vault. Fragile, no rotation, no reconciliation</li></ul><p>There&#39;s no native way to say &quot;this container needs secret X from AWS, keep it updated&quot; without building a custom solution or moving to Kubernetes.</p><p>DSO fills this gap.</p><h2 id="cloud-native-alignment" tabindex="-1">Cloud Native Alignment <a class="header-anchor" href="#cloud-native-alignment" aria-label="Permalink to &quot;Cloud Native Alignment&quot;">​</a></h2><p>DSO follows the reconciliation pattern that is fundamental to cloud-native infrastructure:</p><ol><li><strong>Desired state</strong> — Defined in <code>dso.yaml</code> (which secrets, which provider, which containers)</li><li><strong>Actual state</strong> — What&#39;s currently in the running container&#39;s environment</li><li><strong>Reconciliation loop</strong> — The trigger engine continuously compares desired vs actual state using SHA-256 hashing, and converges them when they diverge</li></ol><p>This is the same pattern used by Kubernetes controllers, Flux, ArgoCD, and the Operator Framework. DSO applies it to Docker.</p><p>Additional cloud-native alignment:</p><ul><li><strong>Pluggable provider model</strong> — Each cloud provider is a separate binary loaded via RPC. Adding a new backend doesn&#39;t require modifying the core agent.</li><li><strong>Observability</strong> — Prometheus metrics for secret fetch latency, cache hits/misses, rotation events, and backend failures. Structured JSON audit logging.</li><li><strong>Declarative configuration</strong> — The YAML config describes desired state, not imperative steps.</li><li><strong>In-memory security model</strong> — Secrets never touch disk. They&#39;re held in process memory and injected via environment variables or tmpfs mounts.</li></ul><h2 id="cncf-landscape-fit" tabindex="-1">CNCF Landscape Fit <a class="header-anchor" href="#cncf-landscape-fit" aria-label="Permalink to &quot;CNCF Landscape Fit&quot;">​</a></h2><p>DSO fits in two areas of the <a href="https://landscape.cncf.io/" target="_blank" rel="noreferrer">CNCF Landscape</a>:</p><h3 id="runtime-→-container-runtime" tabindex="-1">Runtime → Container Runtime <a class="header-anchor" href="#runtime-→-container-runtime" aria-label="Permalink to &quot;Runtime → Container Runtime&quot;">​</a></h3><p>DSO operates at the container runtime layer, injecting secrets directly into Docker containers as they start and updating them while they run.</p><h3 id="provisioning-→-security-compliance" tabindex="-1">Provisioning → Security &amp; Compliance <a class="header-anchor" href="#provisioning-→-security-compliance" aria-label="Permalink to &quot;Provisioning → Security &amp; Compliance&quot;">​</a></h3><p>DSO is fundamentally a security tool. It eliminates static credentials on disk, provides audit-compliant secret rotation, and ensures secrets are sourced from approved cloud providers.</p><p>The closest existing CNCF project is the <strong>External Secrets Operator</strong> — but ESO requires Kubernetes. DSO serves the same purpose for Docker environments.</p><h2 id="why-cncf-sandbox" tabindex="-1">Why CNCF Sandbox <a class="header-anchor" href="#why-cncf-sandbox" aria-label="Permalink to &quot;Why CNCF Sandbox&quot;">​</a></h2><p>We&#39;re applying for Sandbox for three reasons:</p><h3 id="_1-neutral-governance" tabindex="-1">1. Neutral governance <a class="header-anchor" href="#_1-neutral-governance" aria-label="Permalink to &quot;1. Neutral governance&quot;">​</a></h3><p>DSO is currently maintained by a single developer. Moving to CNCF provides neutral governance, which matters for adoption by organizations that need vendor independence.</p><h3 id="_2-community-growth" tabindex="-1">2. Community growth <a class="header-anchor" href="#_2-community-growth" aria-label="Permalink to &quot;2. Community growth&quot;">​</a></h3><p>The Docker secret management problem is widely felt but poorly addressed. Being part of the CNCF ecosystem will help DSO reach the teams that need it — particularly those running Docker Compose in production without Kubernetes.</p><h3 id="_3-long-term-ecosystem-value" tabindex="-1">3. Long-term ecosystem value <a class="header-anchor" href="#_3-long-term-ecosystem-value" aria-label="Permalink to &quot;3. Long-term ecosystem value&quot;">​</a></h3><p>As the cloud-native ecosystem matures, we believe the reconciliation pattern should be available everywhere — not just in Kubernetes. DSO extends cloud-native principles to the broader Docker ecosystem, and CNCF is the right home for that work.</p><h2 id="project-health" tabindex="-1">Project Health <a class="header-anchor" href="#project-health" aria-label="Permalink to &quot;Project Health&quot;">​</a></h2><ul><li>Active development since 2024</li><li>3 major releases (v1, v2, v3)</li><li>4 production cloud providers supported</li><li>Architecture designed for extensibility (pluggable providers, strategy engine)</li><li>CI/CD with security scanning (gosec, govulncheck)</li><li>Comprehensive documentation (VitePress site)</li></ul><h2 id="maintainers" tabindex="-1">Maintainers <a class="header-anchor" href="#maintainers" aria-label="Permalink to &quot;Maintainers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>GitHub</th><th>Affiliation</th></tr></thead><tbody><tr><td>Umair</td><td><a href="https://github.com/umairmd385" target="_blank" rel="noreferrer">@umairmd385</a></td><td>Independent</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="./../ARCHITECTURE.html">ARCHITECTURE.md</a> — Technical deep-dive</li><li><a href="./../GOVERNANCE.html">GOVERNANCE.md</a> — Project governance model</li><li><a href="./../CONTRIBUTING.html">CONTRIBUTING.md</a> — How to contribute</li><li><a href="./../SECURITY.html">SECURITY.md</a> — Security policy</li></ul>',40)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
